mapper.select:
SELECT COUNT(*) FROM `user`
WHERE role = 'USER'
AND status = #{status}

SELECT COUNT(*) FROM usage_event
WHERE create_time >= #{start}
AND module = #{module}

SELECT COUNT(DISTINCT user_id) FROM (
    SELECT user_id FROM usage_event WHERE create_time >= #{start}
    UNION ALL
    SELECT user_id FROM login_log
    WHERE success = 1 AND user_id IS NOT NULL AND create_time >= #{start}
) t

SELECT DATE(create_time) AS `date`, COUNT(DISTINCT user_id) AS `value`
FROM (
    SELECT user_id, create_time FROM usage_event WHERE create_time >= #{start}
    UNION ALL
    SELECT user_id, create_time FROM login_log
    WHERE success = 1 AND user_id IS NOT NULL AND create_time >= #{start}
) t
WHERE create_time < DATE_ADD(#{end}, INTERVAL 1 DAY)
GROUP BY DATE(create_time)

SELECT user_id, DATE(create_time) AS day
FROM (
    SELECT user_id, create_time FROM usage_event WHERE create_time >= #{start}
    UNION
    SELECT user_id, create_time FROM login_log
    WHERE success = 1 AND user_id IS NOT NULL AND create_time >= #{start}
) t
